use proc_macro::TokenStream;
use proc_macro2::TokenStream as TokenStream2;
use quote::{format_ident, quote};
use syn::{parse_macro_input, DeriveInput, Ident, LitInt, LitStr};

/// A re-exported alias so callers can name the token type without depending on
/// `proc-macro2` themselves.
pub type Tokens = TokenStream2;

/// Generates a function named by the supplied identifier.
///
/// ```ignore
/// make_fn!(greet);
/// assert_eq!(greet(), "greet");
/// ```
